var accordion_subjects,createAccordion;$(".accordion-expand-all").click(function(){var n=$(".accordion-content-active");n.length>0?n.slideDown("slow"):toastr.warning(JSR.alert_no_level_class_selected)});$(".accordion-collapse-all").click(function(){$(".accordion-content-active").slideUp("slow")});createAccordion=function(){return $("#accordion").accordion({heightStyle:"content",active:!1,collapsible:!0,icons:{header:"ui-icon-circle-plus",activeHeader:"ui-icon-circle-minus"},beforeActivate:function(n){var t=n.originalEvent.target,i=$(t).hasClass("ui-header-button");if(i)return!1}})};$(function(){accordion_subjects=createAccordion();setTimeout(function(){$(".accordion-expand-all").trigger("click")},1e3)});